/**
 * FSR's JSX element builder: what TSX compiles against where no JSX
 * framework is, a spec's JSX in an application without React and the
 * dialect's placements as plain elements. An element is a description;
 * nothing here mounts or renders one, since FSR is no JSX framework.
 */
import { linkAttributes, type LinkOptions } from "./link.js";
import { pictureParts, type PictureOptions } from "./picture.js";
import { embedParts, type EmbedOptions } from "./embed.js";

export const Fragment: unique symbol = Symbol.for("sf.fragment") as never;

export type FsrComponent = (props: Record<string, unknown>) => FsrNode;

export interface FsrElement {
  type: string | typeof Fragment | FsrComponent;
  props: Record<string, unknown>;
  key?: unknown;
}

export type FsrNode = FsrElement | string | number | bigint | boolean | null | undefined | FsrNode[];

/** The types TypeScript checks a file compiled with `@jsxImportSource @snapfire/fsr-client` against: an element is a description and any tag takes HTML attributes as they are written. */
export namespace JSX {
  export type Element = FsrElement;
  export type ElementType = string | FsrComponent;
  export interface ElementChildrenAttribute {
    children: {};
  }
  export interface IntrinsicAttributes {
    key?: string | number | bigint;
  }
  export interface IntrinsicElements {
    [tag: string]: Record<string, unknown>;
  }
}

export function jsx(type: FsrElement["type"], props: Record<string, unknown> | null, key?: unknown): FsrElement {
  return { type, props: props ?? {}, key };
}

export const jsxs: typeof jsx = jsx;

/** An anchor with the marks the navigator reads. */
export function Link(props: LinkOptions & { children?: FsrNode }): FsrElement {
  return jsx("a", linkAttributes(props));
}

/** The `<picture>` the server writes for the same props. */
export function Picture(props: PictureOptions): FsrElement {
  const { img, sources } = pictureParts(props);
  if (sources === null) return jsx("img", img);
  return jsx("picture", { children: [...sources.map((source) => jsx("source", source)), jsx("img", img)] });
}

/** The element content placed at `#name` goes in: `<div id="name">` unless `as` names another tag, with the other attributes as given. */
export function Place({ name, as = "div", ...attrs }: { name: string; as?: string; [attribute: string]: unknown }): FsrElement {
  return jsx(as, { ...attrs, id: name });
}

/** The region the server writes for an island placed by module id, empty until the browser mounts the island in it. */
export function Mount({ when }: { module: string; props?: Record<string, unknown>; when?: "load" | "visible" | "idle" }): FsrElement {
  return jsx("sf-s", when ? { "data-sf-island": "", "data-sf-when": when } : { "data-sf-island": "" });
}

/** The placeholder the server writes for a video hosted elsewhere, which a click swaps for the player. */
export function Embed(props: EmbedOptions): FsrElement {
  const parts = embedParts(props);
  const face = [...(parts.still ? [jsx("img", parts.still)] : []), jsx("span", { ...parts.title, children: props.title }), jsx("span", { ...parts.play, children: "\u25B6" })];
  return jsx("div", { ...parts.outer, children: jsx("button", { ...parts.button, children: face }) });
}

/** A placement as an element: its child where it stands. */
export function Island(props: { children?: FsrNode }): FsrElement {
  return jsx(Fragment, { children: props.children });
}

export function island<P extends Record<string, unknown>>(component: (props: P) => FsrNode): (props: P) => FsrNode {
  return component;
}

/** A slot as an element: its fallback. */
export function Slot(props: { children?: FsrNode }): FsrElement {
  return jsx(Fragment, { children: props.children });
}

/** The template dialect's context as a description. The server resolves a provider and every read under it, so this runs only in a file nothing mounts and answers the default. */
export interface FsrContext<T> {
  (props: { value: T; children?: FsrNode }): FsrElement;
  readonly __sfContext: T;
  Provider: (props: { value: T; children?: FsrNode }) => FsrElement;
}

export function createContext<T>(defaultValue: T): FsrContext<T> {
  const provide = (props: { value: T; children?: FsrNode }): FsrElement => jsx(Fragment, { children: props.children });
  return Object.assign(provide, { __sfContext: defaultValue, Provider: provide });
}

export function use<T>(context: FsrContext<T>): T {
  return context.__sfContext;
}
